import * as React from 'react';
import { cn } from '@/lib/utils';

export interface ProgressProps extends React.HTMLAttributes<HTMLDivElement> {
  /** Current value between 0 and `max`. */
  value?: number;
  /** Upper bound (default 100). */
  max?: number;
  /** Accessible label announced by screen readers. */
  label?: string;
}

/**
 * Determinate progress bar. Exposes `role="progressbar"` with
 * `aria-valuenow`/`aria-valuemax` so assistive tech reports the exact
 * percentage; the visual track is pure CSS.
 */
const Progress = React.forwardRef<HTMLDivElement, ProgressProps>(
  ({ className, value = 0, max = 100, label, ...props }, ref) => {
    const clamped = Math.min(Math.max(value, 0), max);
    const percent = max > 0 ? (clamped / max) * 100 : 0;

    return (
      <div
        ref={ref}
        role="progressbar"
        aria-valuenow={clamped}
        aria-valuemin={0}
        aria-valuemax={max}
        aria-label={label}
        className={cn('relative h-2 w-full overflow-hidden rounded-full bg-muted', className)}
        {...props}
      >
        <div
          className="h-full bg-primary transition-all duration-300 motion-reduce:transition-none"
          style={{ width: `${percent}%` }}
        />
      </div>
    );
  }
);
Progress.displayName = 'Progress';

export { Progress };

{
  "id": "progress",
  "name": "Progress",
  "tier": "atom",
  "description": "A determinate progress bar with role=progressbar and exact value semantics",
  "designIntent": "Progress shows completion of a known-length task (uploads, installs, multi-step flows). It exposes exact values so assistive tech reports percentages, not just a moving bar.",
  "props": [
    {
      "name": "value",
      "type": "number",
      "defaultValue": "0",
      "required": false,
      "description": "Current value between 0 and max"
    },
    {
      "name": "max",
      "type": "number",
      "defaultValue": "100",
      "required": false,
      "description": "Upper bound of the progress scale"
    },
    {
      "name": "label",
      "type": "string",
      "required": false,
      "description": "Accessible label announced by screen readers"
    },
    {
      "name": "className",
      "type": "string",
      "required": false,
      "description": "Additional CSS classes to apply"
    }
  ],
  "examples": [
    {
      "title": "Upload progress",
      "code": "<Progress value={uploadPercent} label=\"Upload progress\" />",
      "description": "Track an upload percentage"
    },
    {
      "title": "Step completion",
      "code": "<Progress value={step} max={totalSteps} label=\"Setup progress\" />",
      "description": "Progress through a finite set of steps"
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use Progress for indeterminate work",
      "explanation": "When the duration is unknown, use Spinner or StreamingIndicator instead.",
      "example": "// Avoid\n<Progress />\n\n// Prefer\n<Spinner label=\"Loading\" />"
    },
    {
      "title": "Don't animate progress beyond its value",
      "explanation": "Fabricating movement misleads users; only reflect real task progress."
    }
  ],
  "accessibility": [
    {
      "feature": "Progressbar semantics",
      "implementation": "role=\"progressbar\" with aria-valuenow/min/max",
      "userRequirements": "Provide an accessible label describing the task"
    },
    {
      "feature": "Exact values",
      "implementation": "aria-valuenow reflects the clamped value",
      "userRequirements": "Update the value as the task advances"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Labels",
      "guidelines": ["Name the task, not the bar", "Keep to 2-4 words"],
      "goodExamples": ["Upload progress", "Profile setup"],
      "badExamples": ["Loading bar", "Progress"]
    }
  ],
  "compositionRules": [
    {
      "component": "Skeleton",
      "relationship": "Use Skeleton for unknown-length content, Progress for known-length tasks",
      "example": "<Progress value={50} label=\"Upload\" />"
    }
  ],
  "relatedComponents": ["Skeleton", "Spinner"],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.1.0",
  "sourceDir": "progress",
  "exportName": "Progress"
}
